enum TransactionStatus {
    COMPLETED,
    PENDING,
    CANCELLED
}

// Class representing a customer
class Customer {
    private String id;
    private double totalRevenue;
    private int completedTransactions;

    public Customer(String id) {
        this.id = id;
        this.totalRevenue = 0.0;
        this.completedTransactions = 0;
    }

    // Getters and setters for customer properties
    public String getId() { return id; }
    public double getTotalRevenue() { return totalRevenue; }
    public int getCompletedTransactions() { return completedTransactions; }
}

// Class representing a transaction
class Transaction {
    private int id;
    private String customerId;
    private double amount;
    private TransactionStatus status;

    public Transaction(int id, String customerId, double amount, TransactionStatus status) {
        this.id = id;
        this.customerId = customerId;
        this.amount = amount;
        this.status = status;
    }

    // Getters for transaction properties
    public int getId() { return id; }
    public String getCustomerId() { return customerId; }
    public double getAmount() { return amount; }
    public TransactionStatus getStatus() { return status; }
}

// Service class to process transactions
public class TransactionService {
    private Map<String, Customer> customers;

    public TransactionService() {
        this.customers = new HashMap<>();
    }

    // Method to add a transaction
    public void addTransaction(Transaction transaction) {
        if (transaction.getStatus() == TransactionStatus.COMPLETED) {
            if (transaction.getCustomerId() != null && transaction.getAmount() > 0) {
                Customer customer = customers.get(transaction.getCustomerId());
                if (customer == null) {
                    customer = new Customer(transaction.getCustomerId());
                    customers.put(transaction.getCustomerId(), customer);
                }
                customer.getTotalRevenue() += transaction.getAmount();
                customer.getCompletedTransactions++;
            }
        }
    }

    // Method to get customer summaries
    public List<Customer> getCustomerSummaries() {
        List<Customer> sortedCustomers = new ArrayList<>(customers.values());
        Collections.sort(sortedCustomers, Comparator.comparingDouble(customer -> customer.getTotalRevenue())
                .reversed());

        return sortedCustomers;
    }

    public static void main(String[] args) {
        TransactionService service = new TransactionService();

        // Create transactions
        Transaction transaction1 = new Transaction(1, "C1", 100.0, TransactionStatus.COMPLETED);
        Transaction transaction2 = new Transaction(2, null, -50.0, TransactionStatus.PENDING);
        Transaction transaction3 = new Transaction(3, "C1", 200.0, TransactionStatus.COMPLETED);
        Transaction transaction4 = new Transaction(4, "C2", 300.0, TransactionStatus.CANCELLED);

        // Add transactions to the service
        service.addTransaction(transaction1);
        service.addTransaction(transaction2);
        service.addTransaction(transaction3);
        service.addTransaction(transaction4);

        // Get customer summaries
        List<Customer> customerSummaries = service.getCustomerSummaries();

        // Print customer summaries
        for (Customer customer : customerSummaries) {
            System.out.println("Customer ID: " + customer.getId());
            System.out.println("Total Revenue: " + customer.getTotalRevenue());
            System.out.println("Completed Transactions: " + customer.getCompletedTransactions());
            System.out.println();
        }
    }
}
