import java.util.*;
import java.util.stream.Collectors;

// Enum for transaction status
enum TransactionStatus {
    COMPLETED, PENDING, CANCELLED
}

// Class representing a single transaction
class Transaction {
    private final String transactionId;
    private final String customerId;
    private final double amount;
    private final TransactionStatus status;

    public Transaction(String transactionId, String customerId, double amount, TransactionStatus status) {
        this.transactionId = transactionId;
        this.customerId = customerId;
        this.amount = amount;
        this.status = status;
    }

    // Getters
    public String getTransactionId() { return transactionId; }
    public String getCustomerId() { return customerId; }
    public double getAmount() { return amount; }
    public TransactionStatus getStatus() { return status; }
}

// Service class to process transactions and generate customer summaries
class TransactionService {
    // Process a list of transactions and return customer summaries
    public List<CustomerSummary> processTransactions(List<Transaction> transactions) {
        if (transactions == null || transactions.isEmpty()) {
            return Collections.emptyList();
        }

        // Step 1: Filter out non-completed transactions
        List<Transaction> completedTransactions = transactions.stream()
                .filter(t -> t.getStatus() == TransactionStatus.COMPLETED)
                .collect(Collectors.toList());

        // Step 2: Reject invalid transactions (null customerId or non-positive amount)
        List<Transaction> validCompletedTransactions = completedTransactions.stream()
                .filter(t -> t.getCustomerId() != null && t.getAmount() > 0)
                .collect(Collectors.toList());

        // Step 3: Group by customer ID and calculate total revenue and count
        Map<String, CustomerSummary> customerSummariesMap = new HashMap<>();

        for (Transaction transaction : validCompletedTransactions) {
            String customerId = transaction.getCustomerId();
            double amount = transaction.getAmount();

            customerSummariesMap.putIfAbsent(customerId, new CustomerSummary());
            CustomerSummary summary = customerSummariesMap.get(customerId);
            summary.setTotalRevenue(summary.getTotalRevenue() + amount);
            summary.incrementTransactionCount();
        }

        // Step 4: Convert map to list and sort by total revenue (descending)
        List<CustomerSummary> customerSummaries = new ArrayList<>(customerSummariesMap.values());
        customerSummaries.sort((a, b) -> Double.compare(b.getTotalRevenue(), a.getTotalRevenue()));

        return customerSummaries;
    }
}

// Class representing the summary of each customer
class CustomerSummary {
    private double totalRevenue;
    private int transactionCount;

    public void setTotalRevenue(double totalRevenue) {
        this.totalRevenue = totalRevenue;
    }

    public void incrementTransactionCount() {
